//! `setup` (M6 step 7, M7 step 12): the real binary builds a Linux or Windows setup file from a
//! release it packed, and the file is read back the way the runtime reads it (the trailer locator,
//! `SetupTrailer::parse`, then `verify_setup`).
//! Keys are generated by the binary at test time; every command's output, and the setup file
//! itself, is scanned for every secret generated so far.

#![cfg(unix)]

mod common;

use std::cell::RefCell;
use std::fs;
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};
use std::process::Output;

use common::*;
use ed25519_dalek::SigningKey;
use ed25519_dalek::pkcs8::DecodePrivateKey;
use lunepack_codec_lzma::LzmaCodec;
use lunepack_core::pe::{PeHeaders, PeImage};
use lunepack_core::setup::{
    Located, SetupTrailer, TRAILER_MAGIC, TRAILER_SIZE, locate_file, verify_setup,
};
use lunepack_core::{Clock, ClockReading, FsError, FsErrorKind, ReadAt};
use lunepack_crypto::{Ed25519Verifier, Sha256Hasher};
use lunepack_testkit::exe_headers;

const APP: &str = "org.example.hello";
const T0: u64 = 1_800_000_000;
const AT: u64 = T0 + 3600;
const VERSION: &str = "1.2.3";
const TARGET: &str = "linux-x86_64";

struct At(u64);

impl Clock for At {
    fn now_unix_secs(&self) -> u64 {
        self.0
    }
}

struct Bytes(Vec<u8>);

impl ReadAt for Bytes {
    fn size(&self) -> Result<u64, FsError> {
        Ok(self.0.len() as u64)
    }

    fn read_exact_at(&self, offset: u64, buf: &mut [u8]) -> Result<(), FsError> {
        let start = offset as usize;
        match self.0.get(start..start + buf.len()) {
            Some(src) => {
                buf.copy_from_slice(src);
                Ok(())
            }
            None => Err(FsError::new(FsErrorKind::Other, Path::new("setup"), None)),
        }
    }
}

fn s(path: &Path) -> &str {
    path.to_str().expect("utf-8 path")
}

const UPDATE_TOML: &str = r#"
[update]
feed = "https://updates.example.com/hello"
channel = "stable"
health_timeout_secs = 30

[install]
entry = "bin/app"
name = "Hello"
bin = "hello"
publisher = "Example Org"
"#;

/// A 64-bit little-endian static ELF (one `PT_LOAD`), then filler.
fn runtime_elf(machine: u16) -> Vec<u8> {
    let mut h = exe_headers::elf(machine, false, 64 + 56 + 4096);
    h[16..18].copy_from_slice(&3u16.to_le_bytes());
    h[32..40].copy_from_slice(&64u64.to_le_bytes());
    h[54..56].copy_from_slice(&56u16.to_le_bytes());
    h[56..58].copy_from_slice(&1u16.to_le_bytes());
    h[64..68].copy_from_slice(&1u32.to_le_bytes());
    h
}

/// A config, release keys, and one packed release `1.2.3` for `linux-x86_64` with a runtime.
struct World {
    dir: tempfile::TempDir,
    config: PathBuf,
    release: PathBuf,
    runtime: Vec<u8>,
    /// The target the release was packed for and `setup` builds.
    target: &'static str,
    secrets: RefCell<Vec<Vec<u8>>>,
}

/// What a Windows world differs by: the runtime image, extra config, extra input files.
struct Windows {
    runtime: Vec<u8>,
    toml: &'static str,
    /// Files of the input tree.
    files: Vec<(&'static str, Vec<u8>)>,
    /// Files beside the config (a `[windows] icon`).
    beside_config: Vec<(&'static str, Vec<u8>)>,
}

impl World {
    fn new() -> World {
        World::build(None)
    }

    fn windows(spec: Windows) -> World {
        World::build(Some(spec))
    }

    fn build(windows: Option<Windows>) -> World {
        let dir = tempfile::tempdir().unwrap();
        let target = if windows.is_some() { WIN } else { TARGET };
        let w = World {
            config: dir.path().join("lunepack.toml"),
            release: dir.path().join("rel"),
            runtime: match &windows {
                Some(spec) => spec.runtime.clone(),
                None => runtime_elf(62),
            },
            target,
            secrets: RefCell::new(Vec::new()),
            dir,
        };
        let root = w.new_key("root");
        let rel_key = w.new_key("release0");
        assert_ok(
            &w.run(&["init", "--app-id", APP, "--root-key", &root.1], &[]),
            "init",
        );
        {
            use std::io::Write as _;
            let mut f = fs::OpenOptions::new().append(true).open(&w.config).unwrap();
            match &windows {
                Some(spec) => {
                    let toml = UPDATE_TOML.replace("bin/app", "bin/app.exe");
                    f.write_all(toml.as_bytes()).unwrap();
                    f.write_all(spec.toml.as_bytes()).unwrap();
                }
                None => f.write_all(UPDATE_TOML.as_bytes()).unwrap(),
            }
        }
        fs::create_dir(&w.release).unwrap();
        let root_spec = format!("file:{}", s(&root.0));
        let rel_spec = format!("file:{}", s(&rel_key.0));
        let out = w.run(
            &[
                "keys",
                "set",
                "--release-dir",
                s(&w.release),
                "--threshold",
                "1",
                "--release-key",
                &rel_key.1,
                "--sign",
                &root_spec,
            ],
            &[("SOURCE_DATE_EPOCH", &T0.to_string())],
        );
        assert_ok(&out, "keys set");

        for (rel, bytes) in windows.iter().flat_map(|spec| &spec.beside_config) {
            fs::write(w.dir.path().join(rel), bytes).unwrap();
        }
        let input = w.dir.path().join("input");
        let entry = input.join(if windows.is_some() {
            "bin/app.exe"
        } else {
            "bin/app"
        });
        fs::create_dir_all(entry.parent().unwrap()).unwrap();
        let entry_bytes = if windows.is_some() {
            exe_headers::pe(0x8664, 8_000)
        } else {
            exe_headers::elf(62, false, 20_000)
        };
        fs::write(&entry, entry_bytes).unwrap();
        fs::set_permissions(&entry, fs::Permissions::from_mode(0o755)).unwrap();
        for (rel, bytes) in windows.iter().flat_map(|spec| &spec.files) {
            let path = input.join(rel);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(path, bytes).unwrap();
        }
        fs::create_dir_all(input.join("data")).unwrap();
        fs::write(input.join("data/readme.txt"), b"read me\n".repeat(400)).unwrap();
        let runtime = w.dir.path().join("runtime");
        fs::write(&runtime, &w.runtime).unwrap();
        let stub = w.dir.path().join("stub.exe");
        fs::write(&stub, hardened(0x8664, 2)).unwrap();
        let tmp = w.dir.path().join("tmp");
        fs::create_dir(&tmp).unwrap();
        let mut pack = vec![
            "pack",
            "--input",
            s(&input),
            "--version",
            VERSION,
            "--target",
            target,
            "--release-dir",
            s(&w.release),
            "--sign",
            &rel_spec,
            "--runtime",
            s(&runtime),
        ];
        if windows.is_some() {
            pack.extend_from_slice(&["--stub", s(&stub)]);
        }
        let out = w.run(
            &pack,
            &[("SOURCE_DATE_EPOCH", &T0.to_string()), ("TMPDIR", s(&tmp))],
        );
        assert_ok(&out, "pack");
        w
    }

    fn cmd(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let output = run(args, env);
        let secrets = self.secrets.borrow();
        let refs: Vec<&[u8]> = secrets.iter().map(Vec::as_slice).collect();
        assert_no_secrets(&output, &refs);
        output
    }

    fn run(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let mut full = vec!["--config", s(&self.config)];
        full.extend_from_slice(args);
        self.cmd(&full, env)
    }

    /// A key file and its public key; the secret is remembered for the scans.
    fn new_key(&self, name: &str) -> (PathBuf, String) {
        let base = self.dir.path().join(name);
        let out = self.cmd(&["keys", "gen", s(&base)], &[]);
        assert_ok(&out, "keys gen");
        let path = base.with_extension("key");
        let pem = fs::read_to_string(&path).unwrap();
        let seed = SigningKey::from_pkcs8_pem(&pem).unwrap().to_bytes();
        let mut secrets = self.secrets.borrow_mut();
        secrets.push(pem.into_bytes());
        secrets.push(seed.to_vec());
        (path, field(&stdout(&out), "public:"))
    }

    fn setup(&self, out: &Path, extra: &[&str]) -> Output {
        let at = AT.to_string();
        let mut args = vec![
            "setup",
            s(&self.release),
            "--version",
            VERSION,
            "--target",
            self.target,
            "--out",
            s(out),
            "--at",
            &at,
        ];
        args.extend_from_slice(extra);
        self.run(&args, &[])
    }

    fn release_file(&self, rel: &str) -> PathBuf {
        self.release.join(rel)
    }
}

const WIN: &str = "windows-x86_64";

/// A hardened PE image (M7-D10).
fn hardened(machine: u16, subsystem: u16) -> Vec<u8> {
    exe_headers::pe_image(machine, &exe_headers::PeSpec::hardened(subsystem))
}

/// Parses and verifies `bytes` as the runtime does, at `AT`.
fn check(bytes: &[u8]) -> Result<lunepack_core::setup::VerifiedSetup, String> {
    if (bytes.len() as u64) < TRAILER_SIZE {
        return Err("short".into());
    }
    let tail = &bytes[bytes.len() - TRAILER_SIZE as usize..];
    let trailer = SetupTrailer::parse(tail, bytes.len() as u64, &Sha256Hasher, &Ed25519Verifier)
        .map_err(|e| format!("trailer: {e}"))?;
    verify_setup(
        &trailer,
        &Bytes(bytes.to_vec()),
        &ClockReading::read(&At(AT), None),
        &LzmaCodec,
        &Sha256Hasher,
        &Ed25519Verifier,
    )
    .map_err(|e| format!("payload: {e}"))
}

fn trailer_of(bytes: &[u8]) -> SetupTrailer {
    let tail = &bytes[bytes.len() - TRAILER_SIZE as usize..];
    SetupTrailer::parse(tail, bytes.len() as u64, &Sha256Hasher, &Ed25519Verifier).unwrap()
}

#[test]
fn setup_writes_runtime_payload_and_trailer_deterministically() {
    let w = World::new();
    let a = w.dir.path().join("a-setup");
    let b = w.dir.path().join("b-setup");
    let out = w.setup(&a, &[]);
    assert_ok(&out, "setup");
    assert!(
        stdout(&out).starts_with("setup: a-setup ("),
        "{}",
        stdout(&out)
    );
    assert_ok(&w.setup(&b, &[]), "setup again");
    let bytes = fs::read(&a).unwrap();
    assert_eq!(bytes, fs::read(&b).unwrap(), "two runs differ");
    assert_eq!(
        fs::metadata(&a).unwrap().permissions().mode() & 0o777,
        0o755
    );

    // runtime ‖ key set ‖ manifest ‖ pack ‖ trailer, each part 8-byte aligned.
    assert!(bytes.starts_with(&w.runtime));
    assert!(bytes.ends_with(&TRAILER_MAGIC));
    let t = trailer_of(&bytes);
    let part = |p: lunepack_core::setup::SetupPart| {
        assert_eq!(p.offset % 8, 0);
        bytes[p.offset as usize..(p.offset + p.length) as usize].to_vec()
    };
    assert_eq!(part(t.keys), fs::read(w.release_file("keys.json")).unwrap());
    assert_eq!(
        part(t.manifest),
        fs::read(w.release_file(&format!("{VERSION}/{TARGET}.manifest.json"))).unwrap()
    );
    assert_eq!(
        part(t.pack),
        fs::read(w.release_file(&format!("{VERSION}/{TARGET}.pack"))).unwrap()
    );
    assert!(t.keys.offset >= w.runtime.len() as u64);
    assert_eq!(t.version.to_string(), VERSION);
    assert_eq!(t.target.as_str(), TARGET);
    assert_eq!(t.root.app_id().as_str(), APP);

    let verified = check(&bytes).expect("the setup verifies");
    assert_eq!(verified.config.install.name, "Hello");
    assert_eq!(
        verified.config.install.publisher.as_deref(),
        Some("Example Org")
    );
    assert!(verified.installed_bytes() > 0);

    // No key material: only the public root goes into the file.
    let secrets = w.secrets.borrow();
    let refs: Vec<&[u8]> = secrets.iter().map(Vec::as_slice).collect();
    assert_no_secrets(
        &Output {
            status: out.status,
            stdout: bytes,
            stderr: Vec::new(),
        },
        &refs,
    );
}

#[test]
fn an_existing_output_and_an_unsupported_target_are_refused() {
    let w = World::new();
    let a = w.dir.path().join("a-setup");
    fs::write(&a, b"keep").unwrap();
    let err = assert_fails(&w.setup(&a, &[]), 1, "existing out");
    assert!(err.contains("already exists"), "{err}");
    assert_eq!(fs::read(&a).unwrap(), b"keep");

    let b = w.dir.path().join("b-setup");
    let at = AT.to_string();
    let out = w.run(
        &[
            "setup",
            s(&w.release),
            "--version",
            VERSION,
            "--target",
            "macos-aarch64",
            "--out",
            s(&b),
            "--at",
            &at,
        ],
        &[],
    );
    let err = assert_fails(&out, 1, "macos target");
    assert!(err.contains("Linux and Windows targets only"), "{err}");
    // A Windows target the release was not packed for.
    let out = w.run(
        &[
            "setup",
            s(&w.release),
            "--version",
            VERSION,
            "--target",
            WIN,
            "--out",
            s(&b),
            "--at",
            &at,
        ],
        &[],
    );
    assert_fails(&out, 1, "windows target of a Linux release");
    assert!(!b.exists());
    // A version the release does not hold.
    let out = w.run(
        &[
            "setup",
            s(&w.release),
            "--version",
            "9.9.9",
            "--target",
            TARGET,
            "--out",
            s(&b),
            "--at",
            &at,
        ],
        &[],
    );
    assert_fails(&out, 1, "absent version");
    assert!(!b.exists());
}

#[test]
fn a_tampered_release_file_is_refused_before_writing() {
    for rel in [
        "keys.json".to_owned(),
        format!("{VERSION}/{TARGET}.manifest.json"),
        format!("{VERSION}/{TARGET}.pack"),
    ] {
        let w = World::new();
        let path = w.release_file(&rel);
        let mut bytes = fs::read(&path).unwrap();
        let mid = bytes.len() / 2;
        bytes[mid] ^= 0x01;
        fs::write(&path, bytes).unwrap();
        let out_path = w.dir.path().join("setup");
        assert_fails(&w.setup(&out_path, &[]), 1, &rel);
        assert!(!out_path.exists(), "{rel}: a file was written");
    }
}

#[test]
fn the_runtime_check_refuses_a_tampered_truncated_or_overlapping_file() {
    let w = World::new();
    let a = w.dir.path().join("a-setup");
    assert_ok(&w.setup(&a, &[]), "setup");
    let bytes = fs::read(&a).unwrap();
    let t = trailer_of(&bytes);

    // One flipped byte in each part.
    for (name, p) in [("keys", t.keys), ("manifest", t.manifest), ("pack", t.pack)] {
        let mut b = bytes.clone();
        b[(p.offset + p.length / 2) as usize] ^= 0x01;
        assert!(check(&b).is_err(), "{name}");
    }
    // Truncated: a byte short, or the trailer gone.
    assert!(check(&bytes[..bytes.len() - 1]).is_err());
    // (The pack's last byte, and the alignment padding after it, are gone.)
    let mut cut = bytes[..(t.pack.offset + t.pack.length - 1) as usize].to_vec();
    cut.extend_from_slice(&bytes[bytes.len() - TRAILER_SIZE as usize..]);
    assert!(check(&cut).is_err(), "a payload byte short");
    // Overlapping parts: the manifest moved into the key set.
    let mut moved = t.clone();
    moved.manifest.offset = t.keys.offset + 8;
    let mut b = bytes[..bytes.len() - TRAILER_SIZE as usize].to_vec();
    b.extend_from_slice(&moved.encode().unwrap());
    let err = check(&b).unwrap_err();
    assert!(err.contains("overlap"), "{err}");
    // A trailer whose root is not the one the config names (another key, same app).
    let other = lunepack_core::TrustedRoot::from_parts(
        t.root.app_id().clone(),
        1,
        1,
        &[[7u8; 32]],
        &Sha256Hasher,
        &Ed25519Verifier,
    );
    if let Ok(other) = other {
        let mut swapped = t.clone();
        swapped.root = other;
        let mut b = bytes[..bytes.len() - TRAILER_SIZE as usize].to_vec();
        b.extend_from_slice(&swapped.encode().unwrap());
        assert!(check(&b).is_err(), "another root");
    }
    // A wrong target in the trailer.
    let mut wrong = t.clone();
    wrong.target = lunepack_core::Target::LinuxAarch64;
    let mut b = bytes[..bytes.len() - TRAILER_SIZE as usize].to_vec();
    b.extend_from_slice(&wrong.encode().unwrap());
    let err = check(&b).unwrap_err();
    assert!(err.contains("target"), "{err}");
    // Untouched, it verifies.
    check(&bytes).unwrap();
}

// ---- Windows setup files (M7 step 12) -------------------------------------------------------

/// `<name> Setup` etc. in the version info of `pe`.
fn version_strings(pe: &[u8]) -> std::collections::BTreeMap<String, String> {
    let image = editpe::Image::parse(pe.to_vec()).unwrap();
    let info = image
        .resource_directory()
        .and_then(|r| r.get_version_info().ok().flatten())
        .expect("a version info");
    info.strings[0]
        .strings
        .iter()
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect()
}

fn icon_png(side: u32) -> Vec<u8> {
    let mut p = b"\x89PNG\r\n\x1a\n".to_vec();
    p.extend_from_slice(&13u32.to_be_bytes());
    p.extend_from_slice(b"IHDR");
    p.extend_from_slice(&side.to_be_bytes());
    p.extend_from_slice(&side.to_be_bytes());
    p.extend_from_slice(&[8, 6, 0, 0, 0, 0, 0, 0, 0]);
    p
}

fn plain_windows() -> Windows {
    Windows {
        runtime: hardened(0x8664, 2),
        toml: "",
        files: Vec::new(),
        beside_config: Vec::new(),
    }
}

/// The runtime copy of a Windows setup file is stamped as the setup variant, keeps every hardening
/// field of the pack's runtime (P3), is checked as a runtime again, and the file reads back as a
/// setup file through the locator, the trailer and `verify_setup`.
#[test]
fn windows_setup_stamps_the_runtime_and_reads_back() {
    let ico = {
        let mut ico = vec![0, 0, 1, 0, 1, 0, 16, 16, 0, 0, 1, 0, 32, 0];
        ico.extend_from_slice(&4u32.to_le_bytes());
        ico.extend_from_slice(&22u32.to_le_bytes());
        ico.extend_from_slice(b"ICON");
        ico
    };
    let w = World::windows(Windows {
        toml: "\n[windows]\nicon = \"app.ico\"\n",
        beside_config: vec![("app.ico", ico)],
        ..plain_windows()
    });
    let out_path = w.dir.path().join("Hello-Setup.exe");
    assert_ok(&w.setup(&out_path, &[]), "windows setup");
    let bytes = fs::read(&out_path).unwrap();

    // Found as a setup file by the locator the runtime uses; nothing follows the trailer.
    let located = locate_file(&Bytes(bytes.clone())).unwrap();
    assert_eq!(
        located,
        Located::Setup {
            end: bytes.len() as u64
        }
    );
    assert!(bytes.ends_with(&TRAILER_MAGIC));
    let verified = check(&bytes).expect("the setup verifies");
    assert_eq!(verified.config.install.name, "Hello");

    // The runtime part: stamped, hardened as the input was, passing the runtime check.
    let t = trailer_of(&bytes);
    let runtime = &bytes[..t.keys.offset as usize];
    lunepack_core::check_runtime_image(runtime, lunepack_core::Target::WindowsX86_64)
        .expect("a hardened Windows runtime");
    let (before, after) = (
        PeImage::parse(&w.runtime).unwrap(),
        PeImage::parse(runtime).unwrap(),
    );
    assert_eq!(after.headers.machine, before.headers.machine);
    assert_eq!(after.headers.subsystem, before.headers.subsystem);
    assert_eq!(after.imports, before.imports);
    assert_eq!(after.delay_imports, before.delay_imports);
    assert_eq!(after.dependent_load_flags, Some(0x800));
    assert_eq!(after.manifest, before.manifest);
    let strings = version_strings(runtime);
    for (key, value) in [
        ("CompanyName", "Example Org"),
        ("FileDescription", "Hello Setup"),
        ("FileVersion", VERSION),
        ("OriginalFilename", "Hello-Setup.exe"),
        ("ProductName", "Hello"),
        ("ProductVersion", VERSION),
    ] {
        assert_eq!(strings.get(key).map(String::as_str), Some(value), "{key}");
    }
    let image = editpe::Image::parse(runtime.to_vec()).unwrap();
    assert!(
        image
            .resource_directory()
            .unwrap()
            .get_main_icon()
            .unwrap()
            .is_some(),
        "the [windows] icon is stamped"
    );
    // Parts are 8-aligned and nothing was appended after the trailer.
    assert_eq!(t.keys.offset % 8, 0);
    assert_eq!(t.target.as_str(), WIN);
    // The default name carries the extension.
    let again = w.dir.path().join("again.exe");
    assert_ok(&w.setup(&again, &[]), "again");
    let strings = version_strings(&fs::read(&again).unwrap());
    assert_eq!(strings["OriginalFilename"], "again.exe");
}

/// F5: signtool zero-pads to 8 before the certificate table, so a setup file whose length is not a
/// multiple of 8 stops ending at its trailer once signed. The writer aligns the trailer: every
/// setup file is a multiple of 8 long, whatever the pack's length (FORMAT.md 14).
#[test]
fn every_setup_file_is_a_multiple_of_8_long() {
    // Incompressible bytes, so the pack's length moves with the file's.
    let noise = |n: usize| -> Vec<u8> {
        let mut x = 0x9E37_79B9_7F4A_7C15_u64;
        (0..n)
            .map(|_| {
                x ^= x << 13;
                x ^= x >> 7;
                x ^= x << 17;
                (x >> 24) as u8
            })
            .collect()
    };
    let mut residues = std::collections::BTreeSet::new();
    let mut lens = Vec::new();
    for extra in 0..8usize {
        let w = World::windows(Windows {
            files: vec![("data/noise.bin", noise(4_000 + extra))],
            ..plain_windows()
        });
        let out_path = w.dir.path().join("s.exe");
        assert_ok(&w.setup(&out_path, &[]), "windows setup");
        let bytes = fs::read(&out_path).unwrap();
        let t = trailer_of(&bytes);
        residues.insert((t.pack.offset + t.pack.length) % 8);
        lens.push(bytes.len());
        // signtool pads to 8 before the table: a multiple of 8 means it adds nothing.
        assert!(
            bytes.len().is_multiple_of(8),
            "setup file {extra} is not 8-aligned"
        );
        assert_eq!(
            locate_file(&Bytes(bytes.clone())).unwrap(),
            Located::Setup {
                end: bytes.len() as u64
            }
        );
    }
    // The inputs did reach unaligned pack ends, so the test would have caught the old writer.
    assert!(
        residues.iter().any(|r| *r != 0),
        "every pack ended 8-aligned: the test proves nothing ({residues:?})"
    );
    // And the Linux file too.
    let w = World::new();
    let out_path = w.dir.path().join("s");
    assert_ok(&w.setup(&out_path, &[]), "linux setup");
    assert!(fs::read(&out_path).unwrap().len().is_multiple_of(8));
}

/// A PNG `install.icon` is read from the pack through its signed frame and stamped; an SVG stamps
/// none.
#[test]
fn windows_setup_reads_a_png_install_icon_from_the_pack() {
    let icon_of = |w: &World| {
        let out_path = w.dir.path().join("s.exe");
        assert_ok(&w.setup(&out_path, &[]), "setup");
        let bytes = fs::read(&out_path).unwrap();
        let t = trailer_of(&bytes);
        let image = editpe::Image::parse(bytes[..t.keys.offset as usize].to_vec()).unwrap();
        image
            .resource_directory()
            .unwrap()
            .get_main_icon()
            .unwrap()
            .map(<[u8]>::to_vec)
    };
    let w = World::windows(Windows {
        toml: "icon = \"assets/icon.png\"\n",
        files: vec![("assets/icon.png", icon_png(64))],
        ..plain_windows()
    });
    let icon = icon_of(&w).expect("an icon");
    assert!(icon.ends_with(&icon_png(64)), "the PNG's bytes, unchanged");

    let w = World::windows(Windows {
        toml: "icon = \"assets/icon.svg\"\n",
        files: vec![("assets/icon.svg", b"<svg/>".to_vec())],
        ..plain_windows()
    });
    assert!(icon_of(&w).is_none());
}

/// A certificate table on the pack's runtime is stripped from the setup file's copy (M7-D11): the
/// file is a setup file whose data ends at its own end, and the stamped copy carries no table.
#[test]
fn windows_setup_strips_a_signed_runtime() {
    let table = vec![0xAB; 64];
    let unsigned = hardened(0x8664, 2);
    let mut spec = exe_headers::PeSpec::hardened(2);
    spec.security_dir = Some((unsigned.len() as u32, table.len() as u32));
    let mut signed = exe_headers::pe_image(0x8664, &spec);
    signed.extend_from_slice(&table);
    let w = World::windows(Windows {
        runtime: signed,
        ..plain_windows()
    });
    let out_path = w.dir.path().join("s.exe");
    assert_ok(&w.setup(&out_path, &[]), "setup");
    let bytes = fs::read(&out_path).unwrap();
    assert_eq!(
        locate_file(&Bytes(bytes.clone())).unwrap(),
        Located::Setup {
            end: bytes.len() as u64
        }
    );
    let t = trailer_of(&bytes);
    let runtime = &bytes[..t.keys.offset as usize];
    let headers = PeHeaders::parse(runtime, runtime.len() as u64).unwrap();
    assert!(headers.security().is_zero(), "the table is gone");
    assert!(
        !runtime.windows(table.len()).any(|w| w == table.as_slice()),
        "its bytes are gone"
    );
    check(&bytes).expect("verifies");
}

/// A certificate table that is not at the end of the runtime's file is refused, and nothing is
/// written.
#[test]
fn windows_setup_refuses_an_odd_certificate_table() {
    let mut spec = exe_headers::PeSpec::hardened(2);
    spec.security_dir = Some((64, 64));
    let mut odd = exe_headers::pe_image(0x8664, &spec);
    odd.extend_from_slice(&[0; 64]);
    let w = World::windows(Windows {
        runtime: odd,
        ..plain_windows()
    });
    let out_path = w.dir.path().join("s.exe");
    let err = assert_fails(&w.setup(&out_path, &[]), 1, "an odd table");
    assert!(err.contains("certificate table"), "{err}");
    assert!(!out_path.exists());
}
